@router.post("/compute/instances/bulk-tag")
async def bulk_tag_instances(
    payload: TagUpdatePayload,
    current_user: User = Depends(get_current_user)
):
    updated_count = await ComputeInstance.objects.filter(
        id__in=payload.instance_ids,
        account_id=current_user.account_id
    ).update(
        security_zone=payload.security_zone,
        metadata_tags=payload.tags
    )
    return {"updated_instances": updated_count}
